(function(){function init(){const chat=document.getElementById('ariellaDesktopChat');if(!chat)return;const input=chat.querySelector('#ariellaChatInput'),send=chat.querySelector('#ariellaChatSend'),messages=chat.querySelector('#ariellaChatMessages');if(!input||!send||!messages)return;let trolley=false,awaiting=false,confirmed=false;const value=k=>(chat.querySelector('[data-summary-key="'+k+'"] span')?.textContent||'').trim();const clean=v=>v&&v!=='עדיין לא צוין'?v:'';function setBaggage(v){const el=chat.querySelector('[data-summary-key="baggage"] span');if(el){el.textContent=v;el.closest('.ac-detail')?.classList.add('is-filled')}}function naturalSummary(){const destination=clean(value('destination')),dates=clean(value('dates')),travelers=clean(value('travelers')),budget=clean(value('budget')),flight=clean(value('flight')),baggage=trolley?'טרולי / כבודה קטנה עד 8 ק״ג':clean(value('baggage'));let s='אז אנחנו מחפשים חופשה';if(destination)s+=' ל'+destination;if(dates)s+=', '+dates;if(travelers)s+=', עבור '+travelers;s+='.';if(budget){if(/ללא הגבלת/.test(budget))s+=' אין לכם הגבלת תקציב.';else s+=' התקציב הוא '+budget+'.';}if(flight)s+=' מבחינת הטיסה: '+flight+'.';if(baggage){if(/טרולי|8 ק/.test(baggage))s+=' מבחינת כבודה, מספיק לכם טרולי / כבודה קטנה עד 8 ק״ג.';else if(/ללא/.test(baggage))s+=' אתם מעדיפים ללא כבודה.';else s+=' מבחינת כבודה: '+baggage+'.';}return s+'\n\nהאם הכול נכון ואפשר לצאת לחיפוש? אם כן, כתבו "כן" או "מאשר".'}function finalToConfirm(){const bots=messages.querySelectorAll('.ac-row.bot .ac-bubble'),b=bots[bots.length-1];if(!b||confirmed)return;if(/יש לי את הפרטים הבסיסיים|continue to the search|זה הסיכום לאישור/i.test(b.textContent||'')){if(trolley)setBaggage('טרולי / כבודה קטנה עד 8 ק״ג');b.textContent=naturalSummary();awaiting=true;messages.scrollTop=messages.scrollHeight}}function add(who,text){const row=document.createElement('div');row.className='ac-row '+who;if(who==='bot'){const a=document.createElement('div');a.className='ac-mini-avatar';a.textContent='A';row.appendChild(a)}const b=document.createElement('div');b.className='ac-bubble';b.textContent=text;row.appendChild(b);messages.appendChild(row)}send.addEventListener('click',function(e){const raw=input.value.trim(),low=raw.toLowerCase();if(!raw)return;if(awaiting&&/^(כן|מאשר|מאשרת|אישור|yes|confirm)$/.test(low)){e.stopImmediatePropagation();input.value='';add('user',raw);add('bot','מעולה, יוצאים לחיפוש.');confirmed=true;awaiting=false;messages.scrollTop=messages.scrollHeight;return}if(awaiting)awaiting=false;if(/טרולי|כבודה קטנה|כבודת יד|תיק יד|8 קג|8 ק״ג|8 ק"ג/i.test(raw)){trolley=true;if(!/כבודה|מזוודה/i.test(raw))input.value=raw+' כבודה';setTimeout(()=>setBaggage('טרולי / כבודה קטנה עד 8 ק״ג'),260)}else if(/ללא כבודה|בלי כבודה|בלי מזוודה/i.test(raw))trolley=false;setTimeout(finalToConfirm,420)},true);input.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey){const raw=input.value.trim();if(/טרולי|כבודה קטנה|כבודת יד|תיק יד|8 קג|8 ק״ג|8 ק"ג/i.test(raw)&&!/כבודה|מזוודה/i.test(raw)){trolley=true;input.value=raw+' כבודה';setTimeout(()=>setBaggage('טרולי / כבודה קטנה עד 8 ק״ג'),260);setTimeout(finalToConfirm,420)}}},true);new MutationObserver(()=>setTimeout(finalToConfirm,0)).observe(messages,{childList:true,subtree:true})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();